        }
      }
    }
    let obj= [];
    let setss =  new Map();
    for (let[k,v] of tagsMap) {
        var st = k.split(">");
        var str = {};
        str.source = st[0];
        str.target = st[1];
        str.value  = v;
      obj.push(str);
      if(setss.get(st[0]) != null){  
        setss.set(st[0], parseInt(setss.get(st[0]))+100);
      }else{
        setss.set(st[0], 100);
      }
